#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
# docker run --env-file reads this file, so it lives outside the checkout.
ENV_FILE="${ENV_FILE:-$HOME/mua/mua.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any. Single or double
# quotes left by older versions of this wizard, or a dotenv file, are undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value q="'" sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/$q}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
#
# Values are written bare, with no quotes: docker run --env-file takes each
# value literally, so quotes would become part of it. A value can't hold a
# newline.
write_env() {
  local key="$1" value="$2" tmp
  [[ "$value" != *$'\n'* ]] || { warn "$key can't contain a newline"; return 1; }
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: deploy the mua alpha on almere (#134). Run on almere, from the root
# of a checkout of odogono/hero-world:
#
#   packages/mua_server/rel/deploy-almere.sh
#
# ENV_FILE defaults to ~/mua/mua.env, outside the checkout; it is never
# committed. Re-running keeps values already saved. See docs/operations.md.
# ──────────────────────────────────────────────────────────────────────────

CONTAINER="${CONTAINER:-mua}"
IMAGE="${IMAGE:-mua}"
VOLUME="${VOLUME:-mua-data}"

# Character names and where each is, read from the World a container runs.
SUMMARY='s = :sys.get_state(MuaServer.World); IO.puts("world_time=#{MuaWorld.world_time(MuaServer.World)}"); for e <- OdgnEcs.query(s.world, with: ["player"]), do: IO.puts("#{OdgnEcs.get(s.world, e, "player")["name"]} in #{inspect((OdgnEcs.get(s.world, e, "location") || %{})["in"])}")'

# unquote_env_file rewrites any quoted KEY='value' lines left in ENV_FILE by an
# older version of this wizard, which docker would read with the quotes.
unquote_env_file() {
  [[ -f "$ENV_FILE" ]] || return 0
  local key value
  for key in $(sed -nE "s/^([A-Za-z_][A-Za-z0-9_]*)=[\"'].*/\1/p" "$ENV_FILE"); do
    value=$(_existing "$key") || { warn "couldn't unquote $key in $ENV_FILE; fix it by hand"; continue; }
    write_env "$key" "$value"
  done
}

# configured KEY... succeeds when ENV_FILE already holds a value for every KEY.
configured() {
  local key
  for key in "$@"; do [[ -n "$(_existing "$key" || true)" ]] || return 1; done
}

# keep_saved "what" asks whether to keep what a previous run saved; Enter keeps.
keep_saved() {
  say "$1 is already saved in $ENV_FILE."
  ! confirm "Set it up again?"
}

wait_healthy() {
  local port="$1" i
  for i in $(seq 1 60); do
    if curl -fsS "http://127.0.0.1:$port/health" 2>/dev/null; then printf '\n'; return 0; fi
    sleep 2
  done
  warn "no healthy answer on port $port after 2 minutes; check: docker logs"
  return 1
}

run_wizard() {

TOTAL_STAGES=9

banner "Deploy the mua alpha on almere"

# ── 1 ──────────────────────────────────────────────────────────────────────
stage "Check almere"
[[ -f Dockerfile && -d packages/mua_server ]] || { warn "run this from the root of the hero-world checkout"; exit 1; }
for tool in docker tailscale curl openssl; do
  command -v "$tool" >/dev/null 2>&1 || { warn "$tool is not installed on this machine"; exit 1; }
done
docker info >/dev/null 2>&1 || { warn "docker isn't running, or this user can't use it"; exit 1; }
HOST=$(tailscale status --json | sed -n 's/.*"DNSName": *"\([^"]*\)\.".*/\1/p' | head -n1)
[[ -n "$HOST" ]] || { warn "couldn't read this machine's MagicDNS name; is tailscale up?"; exit 1; }
say "This machine's tailnet name is ${BOLD}$HOST${RESET}."
note "Browsers will reach the alpha at https://$HOST, and only from the tailnet."
note "MagicDNS and HTTPS certificates must be on for the tailnet:"
note "https://login.tailscale.com/admin/dns"
mkdir -p "$(dirname "$ENV_FILE")"
unquote_env_file
write_env PHX_HOST "$HOST"
pause

# ── 2 ──────────────────────────────────────────────────────────────────────
stage "Google: consent screen in Testing mode"
REDO_GOOGLE=1
if configured GOOGLE_CLIENT_ID GOOGLE_CLIENT_SECRET; then
  note "Client ID $(_existing GOOGLE_CLIENT_ID | cut -c1-20)…"
  note "Its redirect URI must still be https://$HOST/auth/google/callback."
  keep_saved "A Google OAuth client" && REDO_GOOGLE=0
fi
if (( REDO_GOOGLE )); then
open_url "https://console.cloud.google.com/auth/overview"
step "Pick or create a project for mua (top bar project picker)."
step "If asked, 'Get started': app name 'mua', your support email, audience External."
step "Audience → Publishing status must say 'Testing' (don't publish the app)."
step "Audience → Test users → Add users: every Google account that will play,"
note "  including both accounts you'll use for the two-browser journey."
pause "Press Enter once the test users are added."
fi

# ── 3 ──────────────────────────────────────────────────────────────────────
stage "Google: OAuth client"
if (( REDO_GOOGLE )); then
open_url "https://console.cloud.google.com/auth/clients"
step "Create client → Application type 'Web application', name 'mua almere'."
step "Authorized redirect URIs → Add URI, exactly:"
say  "    ${BOLD}https://$HOST/auth/google/callback${RESET}"
step "Create, then copy the Client ID and Client secret from the dialog."
warn "If Google rejects the ts.net URI, stop here: the fallback is tailscale funnel."
ask GOOGLE_CLIENT_ID "Paste the Client ID:"
ask_secret GOOGLE_CLIENT_SECRET "Paste the Client secret:"
write_env GOOGLE_CLIENT_ID "$GOOGLE_CLIENT_ID"
write_env GOOGLE_CLIENT_SECRET "$GOOGLE_CLIENT_SECRET"
pause
else
  note "Keeping the saved Google client."
fi

# ── 4 ──────────────────────────────────────────────────────────────────────
stage "Who may play, and who is an Admin"
say "Comma-separated Google emails. Changing them later means editing"
say "$ENV_FILE and restarting the container (docker restart $CONTAINER)."
if configured MUA_ALLOWLIST MUA_ADMINS; then
  note "Allowlist: $(_existing MUA_ALLOWLIST)"
  note "Admins:    $(_existing MUA_ADMINS)"
fi
if ! configured MUA_ALLOWLIST MUA_ADMINS || ! keep_saved "Who may play"; then
  ask MUA_ALLOWLIST "Allowlist (both your accounts, plus known testers):"
  ask MUA_ADMINS "Admins (your main address):"
  write_env MUA_ALLOWLIST "$MUA_ALLOWLIST"
  write_env MUA_ADMINS "$MUA_ADMINS"
fi
if [[ -z "$(_existing SECRET_KEY_BASE || true)" ]]; then
  write_env SECRET_KEY_BASE "$(openssl rand -base64 48 | tr -d '\n')"
else
  note "SECRET_KEY_BASE already set; keeping it so sessions survive."
fi
[[ -n "$(_existing MUA_STARTING_ROOM || true)" ]] || write_env MUA_STARTING_ROOM west_of_house
chmod 600 "$ENV_FILE"
pause

# ── 5 ──────────────────────────────────────────────────────────────────────
stage "Build the release image"
say "Builds $IMAGE from this checkout ($(git rev-parse --short HEAD)). Takes a few minutes."
pause "Press Enter to build."
docker build -t "$IMAGE" .
pause

# ── 6 ──────────────────────────────────────────────────────────────────────
stage "Start the server and serve it on the tailnet"
if docker container inspect "$CONTAINER" >/dev/null 2>&1; then
  warn "a container named $CONTAINER already exists."
  confirm "Replace it? Its World stays on the $VOLUME volume." || { warn "left as it was"; exit 1; }
  docker rm -f "$CONTAINER" >/dev/null
fi
docker run -d --name "$CONTAINER" --restart unless-stopped \
  -p 127.0.0.1:4000:4000 -v "$VOLUME:/data" --env-file "$ENV_FILE" "$IMAGE" >/dev/null
say "Waiting for /health…"
wait_healthy 4000
tailscale serve --bg http://127.0.0.1:4000
note "tailscale serve status:"
tailscale serve status
open_url "https://$HOST"
step "Sign in with Google; you should reach character creation."
step "Try an account NOT on the allowlist (a private window): it must be refused."
pause

# ── 7 ──────────────────────────────────────────────────────────────────────
stage "Two browsers"
say "Browser A and browser B (or two profiles), each signed in as one of your accounts."
step "Both Characters enter and see each other in the same room."
step "A says something; B sees it. B moves away and back; A sees both."
step "A picks up an item; B sees it go. A drops it; B can take it."
step "A scripted interaction (e.g. open the window east of the house) shows to both."
step "Takeover: open A's account in a third tab; the old tab is replaced, its command doesn't run."
step "Disconnect: close B; within 30s reopen it and B is still in place."
step "Reconnect after 30s+: B came back from Limbo to where it was."
pause "Press Enter, then the server restarts; keep both tabs open."
docker restart "$CONTAINER" >/dev/null
wait_healthy 4000
step "Both browsers reconnect by themselves and carry on where they were."
pause

# ── 8 ──────────────────────────────────────────────────────────────────────
stage "Admin live edit (#91)"
say "In the browser signed in as an Admin, type a NorthTalk line at the prompt"
say "starting with ';' that visibly changes the room (e.g. a description),"
step "and check the other browser sees the change."
step "Note the line you used; it goes in the #134 comment."
pause

# ── 9 ──────────────────────────────────────────────────────────────────────
stage "Back up, restore into a clean instance, verify"
out=$(docker exec "$CONTAINER" bin/mua_server rpc 'MuaServer.Release.backup()')
say "$out"
BACKUP=$(printf '%s' "$out" | sed -n 's/.*Backed up the World to \(.*\)$/\1/p' | tail -n1)
[[ -n "$BACKUP" ]] || { warn "couldn't read the backup path"; exit 1; }
say "Live World at backup time:"
docker exec "$CONTAINER" bin/mua_server rpc "$SUMMARY"
docker rm -f mua-restored >/dev/null 2>&1 || true
docker volume rm mua-restored >/dev/null 2>&1 || true
docker volume create mua-restored >/dev/null
docker run --rm -v "$VOLUME:/live:ro" -v mua-restored:/data --env-file "$ENV_FILE" "$IMAGE" \
  bin/mua_server eval "MuaServer.Release.restore(\"/live${BACKUP#/data}\")"
docker run -d --name mua-restored -p 127.0.0.1:4001:4000 -v mua-restored:/data --env-file "$ENV_FILE" "$IMAGE" >/dev/null
wait_healthy 4001
say "Restored World:"
docker exec mua-restored bin/mua_server rpc "$SUMMARY"
step "The same Characters, in the same places; world_time no earlier than the backup's."
pause
if confirm "Remove the restored instance and its volume now?"; then
  docker rm -f mua-restored >/dev/null
  docker volume rm mua-restored >/dev/null
fi

finish
say "Post the results on https://github.com/odogono/hero-world/issues/134:"
say "commit $(git rev-parse --short HEAD), each journey step, the ';' line, the backup path"
say "and both summaries. Copy $BACKUP off the machine if you want to keep it."
}

run_wizard "$@"; exit
